#!/usr/bin/env python3
"""Generate the structural query set from the PDF outlines. Deterministic.

EVAL-2 asks whether navigating a document's section hierarchy helps questions
that name a chapter or a section ("what does section 4.2 say about loops?").
This script turns the outlines `outline.py` extracted into answerable queries
with page-level gold, in the same BEIR/TREC layout every other kb-eval set
uses.

**These queries are template-generated by the author, not human-judged.**
That is the central caveat: the gold is whatever the PDF's own outline says the
section spans, so the set measures "can a retriever find the pages the outline
assigns to this heading", not "are these the pages a person would call
relevant". The README records the templates and the known biases.

Gold pages. A section's gold is its first five pages (grade 2 for the heading
page, grade 1 for the next four). Full chapter spans run to 30+ pages, and
nDCG@10 only looks at ten results: marking 30 pages relevant makes the ideal
ranking unreachable and every system's score a small number that is hard to
move. Five pages is the heading plus the opening of the section, which is what
"what does chapter 2 say" should land on.

Determinism. Fixed seed 42, every candidate list sorted before sampling, no
clock and no network. Re-running the script rewrites byte-identical outputs.

Usage (from the repo root):

    python3 rust/crates/kb-eval/scripts/generate_structural.py
"""

from __future__ import annotations

import argparse
import json
import random
import re
from pathlib import Path
from typing import Any

SEED = 42
DEFAULT_OUTLINES = "rust/crates/kb-eval/sets/structural/outlines.json"
DEFAULT_OUT = "rust/crates/kb-eval/sets/structural"
GOLD_PAGES = 5

# How each document is named in a query, and which corpus it belongs to.
# The alias is what a person would type; the outline's own /Title is sometimes
# "Subject:" or a 60-character report title.
DOCS: dict[str, dict[str, str]] = {
    "Introduction_to_Python_Programming": {
        "corpus": "cs",
        "name": "Introduction to Python Programming",
        "mention": "the Python book",
    },
    "Introduction_to_Computer_Science": {
        "corpus": "cs",
        "name": "Introduction to Computer Science",
        "mention": "the Introduction to Computer Science textbook",
    },
    "joint_employment_report_2025-KE0125018ENN": {
        "corpus": "hr",
        "chapter_level": True,
        "name": "the Joint Employment Report 2025",
        "mention": "the Joint Employment Report 2025",
    },
    "employment_and_social_developments_in_europe_2024-KEBD24002ENN": {
        "corpus": "hr",
        "name": "the 2024 Employment and Social Developments in Europe report",
        "mention": "the 2024 Employment and Social Developments in Europe report",
    },
    "future-oriented_occupations_in_the_eu-KE0125043ENN": {
        "corpus": "hr",
        "chapter_level": True,
        "name": "the Future-oriented Occupations in the EU report",
        "mention": "the Future-oriented Occupations in the EU report",
    },
    "undeclared_care_work_in_the_eu-TJ0125004ENN": {
        "corpus": "hr",
        "name": "the report on undeclared care work in the EU",
        "mention": "the report on undeclared care work in the EU",
    },
}

DOTTED = re.compile(r"^(\d+(?:\.\d+)+)\.?\s+(.+)$")
CHAPTER = re.compile(r"^Chapter\s+(\d+)\b[.:]?\s*(.*)$", re.I)

STOPWORDS = set(
    """a about above after again against all also an and any are as at be because been
    before being below between both but by can could did do does doing down during each
    few for from further had has have having he her here hers herself him himself his how
    i if in into is it its itself just me more most my myself no nor not now of off on once
    only or other our ours ourselves out over own same she should so some such than that
    the their theirs them themselves then there these they this those through to too under
    until up very was we were what when where which while who whom why will with would you
    your yours yourself yourselves""".split()
)

# Titles that carry no topic: asking "what does section 1.1 say about background"
# measures nothing but the number matcher.
GENERIC = {
    "introduction", "background", "summary", "conclusion", "conclusions",
    "references", "chapter review", "chapter summary", "key messages",
    "key indicators", "overview", "contents", "preface", "annex", "annexes",
    "appendix", "key findings", "main findings", "further reading", "glossary",
    "index", "bibliography", "acknowledgements", "foreword",
    "executive summary", "policy pointers", "policy implications", "outlook",
    "limitations",
}

GENERIC_WORDS = {word for phrase in GENERIC for word in phrase.split()}

PLAN = [
    # template, corpus, count
    ("section_topic", "cs", 13),
    ("section_topic", "hr", 13),
    ("section_number", "cs", 8),
    ("section_number", "hr", 6),
    ("section_title", "cs", 8),
    ("section_title", "hr", 13),
    ("chapter_number", "cs", 8),
    ("chapter_number", "hr", 2),
    ("chapter_title", "cs", 2),
    ("chapter_title", "hr", 7),
]


def content_words(text: str) -> list[str]:
    words = re.findall(r"[A-Za-z][A-Za-z'-]+", text.lower())
    return [word for word in words if word not in STOPWORDS]


def strip_numbering(title: str) -> str:
    for pattern in (DOTTED, CHAPTER):
        match = pattern.match(title)
        if match:
            return match.group(2).strip() if pattern is CHAPTER else match.group(2).strip()
    match = re.match(r"^(\d+)\.?\s+(.+)$", title)
    if match:
        return match.group(2).strip()
    return title.strip()


def topic_of(title: str) -> str:
    """A short, natural topic phrase from a heading: content words, lower-case."""
    words = [word for word in content_words(strip_numbering(title))
             if word not in GENERIC_WORDS]
    return " ".join(words[:7])


def is_generic(title: str) -> bool:
    bare = re.sub(r"[^a-z0-9]+", " ", strip_numbering(title).lower()).strip()
    return bare in GENERIC or len(content_words(bare)) < 2


def numeric_of(title: str) -> str | None:
    match = DOTTED.match(title)
    return match.group(1).rstrip(".") if match else None


def chapter_of(title: str) -> str | None:
    match = CHAPTER.match(title)
    return match.group(1) if match else None


def candidates(documents: dict[str, Any], corpus: str) -> dict[str, list[dict[str, Any]]]:
    pool: dict[str, list[dict[str, Any]]] = {
        "section_topic": [],
        "section_number": [],
        "section_title": [],
        "chapter_number": [],
        "chapter_title": [],
    }
    for key in sorted(documents):
        config = DOCS.get(key)
        document = documents[key]
        if not config or config["corpus"] != corpus:
            continue
        # A document whose bookmark order goes backwards has unreliable spans;
        # the one such report (labour market and wage developments) is left out
        # rather than given a gold page range that is knowingly wrong.
        if document.get("out_of_order_nodes", 0):
            continue
        numbers = [numeric_of(node["title"]) for node in document["nodes"]]
        duplicate_numbers = {number for number in numbers if number and numbers.count(number) > 1}
        chapters = [chapter_of(node["title"]) for node in document["nodes"]]
        duplicate_chapters = {number for number in chapters if number and chapters.count(number) > 1}
        bare_titles = [strip_numbering(node["title"]).strip().lower() for node in document["nodes"]]
        duplicate_titles = {title for title in bare_titles if bare_titles.count(title) > 1}
        for node in document["nodes"]:
            title = node["title"]
            base = {
                "doc": key,
                "node": node["id"],
                "title": title,
                "level": node["level"],
                "page": node["page"],
                "end_page": node["end_page"],
            }
            number = numeric_of(title)
            chapter = chapter_of(title)
            span = node["end_page"] - node["page"] + 1
            if number and node["level"] >= 2 and number not in duplicate_numbers:
                pool["section_number"].append(base)
                if not is_generic(title):
                    pool["section_topic"].append(base)
                    if strip_numbering(title).strip().lower() not in duplicate_titles:
                        pool["section_title"].append(base)
            if chapter and chapter not in duplicate_chapters and node["level"] == 1 and span >= 4:
                pool["chapter_number"].append(base)
                if not is_generic(title):
                    pool["chapter_title"].append(base)
            # A report chapter is often not titled "Chapter N": level 1, long,
            # unnumbered, e.g. "Employment and social reforms - Member States'
            # performance and action". Those are real chapter-level targets.
            if (
                config.get("chapter_level")
                and node["level"] == 1
                and not chapter
                and not number
                and span >= 4
                and not is_generic(title)
                and not re.match(r"^(annex|appendix|references)\b", title, re.I)
            ):
                pool["chapter_title"].append(base)
    return pool


def choose(rng: random.Random, items: list[dict[str, Any]], count: int, used: set[str]) -> list[dict[str, Any]]:
    """Deterministic sample preferring nodes not already targeted."""
    items = sorted(items, key=lambda item: (item["doc"], item["page"], item["node"]))
    fresh = [item for item in items if f"{item['doc']}/{item['node']}" not in used]
    chosen = rng.sample(fresh, min(count, len(fresh)))
    if len(chosen) < count:
        rest = [item for item in items if item not in chosen]
        chosen += rng.sample(rest, min(count - len(chosen), len(rest)))
    for item in chosen:
        used.add(f"{item['doc']}/{item['node']}")
    return chosen


def phrase(template: str, node: dict[str, Any], rng: random.Random, variant: int) -> str:
    config = DOCS[node["doc"]]
    doc = config["mention"] if variant % 2 == 0 else config["name"]
    topic = topic_of(node["title"]) or strip_numbering(node["title"]).lower()
    title = strip_numbering(node["title"]).strip().rstrip(".")
    number = numeric_of(node["title"]) or chapter_of(node["title"])
    options = {
        "section_topic": [
            f"What does section {number} of {doc} say about {topic}?",
            f"What does {doc} cover in section {number} on {topic}?",
            f"In {doc}, what does section {number} explain about {topic}?",
        ],
        "section_number": [
            f"Summarise section {number} of {doc}.",
            f"What is in section {number} of {doc}?",
            f"Give me the contents of section {number} of {doc}.",
        ],
        "section_title": [
            f'In {doc}, what is covered in the section titled "{title}"?',
            f"According to {doc}, what does the section on {topic} discuss?",
            f"Find the part of {doc} that explains {topic}.",
        ],
        "chapter_number": [
            f"What does chapter {number} of {doc} cover?",
            f"Summarise chapter {number} of {doc}.",
            f"In {doc}, what is chapter {number} about?",
        ],
        "chapter_title": [
            f"In {doc}, what is in the chapter on {topic}?",
            f"What does {doc} discuss in its chapter on {topic}?",
            f"Summarise the chapter of {doc} about {topic}.",
        ],
    }[template]
    return options[variant % len(options)]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--outlines", type=Path, default=Path(DEFAULT_OUTLINES))
    parser.add_argument("--out", type=Path, default=Path(DEFAULT_OUT))
    args = parser.parse_args()

    outlines = json.loads(args.outlines.read_text(encoding="utf-8"))
    documents = outlines["documents"]
    rng = random.Random(SEED)

    pools = {corpus: candidates(documents, corpus) for corpus in ("cs", "hr")}
    used: set[str] = set()
    queries: list[dict[str, Any]] = []
    qrels: list[tuple[str, str, int]] = []
    for template, corpus, count in PLAN:
        chosen = choose(rng, pools[corpus][template], count, used)
        if len(chosen) < count:
            raise SystemExit(
                f"only {len(chosen)} candidates for {template}/{corpus}, need {count}"
            )
        for index, node in enumerate(chosen):
            qid = f"sq{len(queries) + 1:03d}"
            text = phrase(template, node, rng, index + len(queries))
            gold_end = min(node["end_page"], node["page"] + GOLD_PAGES - 1)
            pages = list(range(node["page"], gold_end + 1))
            for offset, page in enumerate(pages):
                qrels.append((qid, f"{node['doc']}#p{page}", 2 if offset == 0 else 1))
            queries.append(
                {
                    "_id": qid,
                    "text": text,
                    "template": template,
                    "corpus": corpus,
                    "document": node["doc"],
                    "node": node["node"],
                    "title": node["title"],
                    "level": node["level"],
                    "page": node["page"],
                    "end_page": node["end_page"],
                    "gold_pages": pages,
                }
            )

    args.out.mkdir(parents=True, exist_ok=True)
    with (args.out / "queries.jsonl").open("w", encoding="utf-8") as handle:
        for query in queries:
            handle.write(json.dumps({"_id": query["_id"], "text": query["text"]},
                                    ensure_ascii=False) + "\n")
    with (args.out / "query-meta.jsonl").open("w", encoding="utf-8") as handle:
        for query in queries:
            handle.write(json.dumps(
                {k: v for k, v in query.items() if k != "text"}, ensure_ascii=False) + "\n")
    (args.out / "qrels").mkdir(exist_ok=True)
    with (args.out / "qrels" / "test.tsv").open("w", encoding="utf-8") as handle:
        handle.write("# qid\tcorpus-id\tscore\n")
        handle.write("# Template-generated from the PDF outlines by generate_structural.py.\n")
        for qid, page_id, grade in qrels:
            handle.write(f"{qid}\t{page_id}\t{grade}\n")

    print(f"wrote {len(queries)} queries, {len(qrels)} page judgements to {args.out}")
    for template, corpus, count in PLAN:
        print(f"  {template:16s} {corpus}  {count}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
